/** Joint and independent existential antecedents preserve their different family semantics. */
final class ContextCompoundExistential {
    static int checks;static final int WORK=64000000;
    static void require(boolean value,String why){++checks;if(!value)throw new AssertionError(why);}
    static void verdict(ContextUniversalCandidate.Evaluation e,boolean safe,boolean candidateRule,String rule,String candidate,String a,String b,String deny){
        require(e.status==(safe?Status.CONSISTENT:Status.COLLISION),"scope-sensitive family verdict: "+e.status+" / "+e.reason);
        if(safe){ContextUniversalFamilyModel.Certificate cert=e.qualification.certificate;require(cert!=null&&e.qualification.collision==null&&cert.cuts.size()==4,"all four cuts have complete consistent models");List<ContextUniversalUnitRounds.Receipt> receipts=new ArrayList<>();List<ContextUniversalQuotientModel.Model> models=new ArrayList<>();for(ContextUniversalFamilyModel.Cut c:cert.cuts){require(c.receipt.verified&&c.receipt.input==cert.input&&c.model.ledger==c.receipt.closureStep.input,"exact model/closure/common-frontier bindings");receipts.add(c.receipt);models.add(c.model);}require(ContextUniversalFamilyModel.certify(cert.input,receipts,models,16,65536,WORK).certified,"independent all-admissible-value recertification");}
        else collision(e.qualification,e.artifact.foreign,e.artifact.staged,candidateRule,rule,candidate,a,b,deny);
    }
    static void collision(ContextUniversalFamilyInspection.Result r,List<Snapshot> foreign,Snapshot staged,boolean candidateRule,String rule,String candidate,String a,String b,String deny){
        require(r.status==Status.COLLISION&&r.certificate==null&&r.collision!=null&&!r.collision.oppositions.isEmpty(),"complete scope-sensitive contradiction");Set<Source> expectedForeign=new HashSet<>();for(Snapshot f:foreign)for(Entry e:f.primary)if(e.statement.equals(deny)||(!candidateRule&&e.statement.equals(rule)))expectedForeign.add(e.source);require(expectedForeign.size()==(candidateRule?1:2),"exact whole foreign rule/Deny Sources");Set<Source> expectedLocal=new HashSet<>();if(staged!=null)for(Entry e:staged.primary)if(e.statement.equals(candidate)||e.statement.equals(a)||(candidateRule&&e.statement.equals(b)))expectedLocal.add(e.source);
        for(ContextUniversalUnitProof.Proof p:r.collision.oppositions){Set<Source> local=new HashSet<>(),other=new HashSet<>();for(Source s:p.support.sources)(s.localX?local:other).add(s);require(p.dependsOnX&&p.contradiction&&p.conclusion==null&&p.support.sources.size()==4&&local.size()==(candidateRule?3:2)&&other.equals(expectedForeign),"only four necessary whole Sources, no Other/marker contamination");if(staged!=null)require(local.equals(expectedLocal),"exact candidate and antecedent fact Sources");}
    }
    static void one(boolean negative,boolean reverse,boolean nativePath,boolean shared,int mode,boolean candidateRule)throws Exception{
        Path dir=Files.createTempDirectory("compound-existential-write-");System.setProperty("user.home",dir.toString());String s=negative?"~":"",op=negative?"":"~",a="!"+s+"a(1);",b="!"+s+"b("+(mode==1?2:1)+");",deny="!"+op+"q();",rule=shared?"!($x ("+s+"a(x)&&"+s+"b(x)))->"+s+"q();":"!(($x "+s+"a(x))&&($y "+s+"b(y)))->"+s+"q();",candidate=candidateRule?rule:(mode==2?"!safe(1);":b);boolean safe=mode==2||(shared&&mode==1);
        ContextSevenPremiseNativeWriteRunner.create(dir,"Bridge",candidateRule?"!bridgeMarker(2);":rule);ContextSevenPremiseNativeWriteRunner.create(dir,"Deny",deny);ContextSevenPremiseNativeWriteRunner.create(dir,"Other","!other(2);");Set<String> settled;List<RevisionRef> pins;long afterRevision;
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){
            require(f.root.compile(a+(candidateRule&&mode!=2?" "+b:""),null,false),"only available original antecedent facts");for(String name:reverse?new String[]{"Other","Deny","Bridge"}:new String[]{"Bridge","Deny","Other"})f.db.connectContext(name);f.db.saveConnections(f.root);
            ContextProductionInventory before=ContextSevenPremiseNativeWriteRunner.inventory(f);Set<String> origins=ContextSevenPremiseNativeWriteRunner.origins(before);long revision=f.db.getRevision();int rules=f.root.getRules().size();pins=ContextSevenPremiseNativeWriteRunner.pins(f);List<String> foreignPrints;
            try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){foreignPrints=ContextForeignAntecedentQuantifier.fingerprints(lease.inventory());ContextProductionSnapshotSession.Binding bound=lease.bind(WORK,500000);require(bound.foreign.size()==3,"all three private cuts bound");if(!candidateRule){Entry e=bound.foreign.stream().flatMap(v->v.primary.stream()).filter(v->v.statement.equals(rule)).findFirst().get();require(e.kind==Kind.CLAUSES&&e.witnesses()==0&&e.clauses.size()==1&&e.clauses.get(0).variables.size()==(shared?1:2),"whole private compound rule preserves variable sharing without witnesses");}}
            ContextUniversalCandidate.Evaluation diagnostic=f.db.qualifyUniversalProductionCandidate(f.root,candidate,1000,16,16,16,65536,1000000,WORK,500000,WORK);verdict(diagnostic,safe,candidateRule,rule,candidate,a,b,deny);require(f.db.getRevision()==revision&&ContextSevenPremiseNativeWriteRunner.inventory(f).fingerprint.equals(before.fingerprint),"diagnostic preserves physical source");
            if(nativePath){ContextPendingNativeWrite attempt=f.db.beginUniversalWrite(f.root,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK);try{ContextProductionCommitException failure=null;try{f.root.query(candidate,null,false);}catch(ContextProductionCommitException caught){failure=caught;}if(safe)require(failure==null,"actual scope-compatible native publication");else{require(failure!=null&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&failure.getFamilyAudit()!=null&&failure.getFamilyAudit().verified&&failure.getFamilyAudit().verdict!=diagnostic.qualification,"native conflict freshly audited in actual pending child");collision(failure.getFamilyAudit().verdict,diagnostic.artifact.foreign,null,candidateRule,rule,candidate,a,b,deny);}}finally{f.db.endNativeWrite(attempt);}}
            else{DB.UniversalProductionWriteResult result=f.db.writeUniversalProductionCandidate(f.root,candidate,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK,false);require(result.status==(safe?DB.ProductionWriteStatus.PUBLISHED:DB.ProductionWriteStatus.COLLISION)&&result.trial!=diagnostic&&result.audit!=null&&result.audit.verified&&result.audit.evaluation==result.trial,"fresh exact public trial/audit governs scope verdict");verdict(result.trial,safe,candidateRule,rule,candidate,a,b,deny);require(result.before.getRevision()==revision&&result.after.getRevision()==f.db.getRevision(),"actual public physical references");}
            ContextProductionInventory after=ContextSevenPremiseNativeWriteRunner.inventory(f);settled=ContextSevenPremiseNativeWriteRunner.origins(after);afterRevision=f.db.getRevision();Set<String> expected=new HashSet<>(origins);if(safe)expected.add(candidate);require(settled.equals(expected)&&after.primary.size()==expected.size()&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"only whole proposed Source publishes, no foreign/derived primary imports");if(safe)require(afterRevision>revision,"safe physical publication advances revision");else require(afterRevision==revision&&f.root.getRules().size()==rules&&after.fingerprint.equals(before.fingerprint),"conflict preserves exact revision/rules/fingerprint");try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){require(ContextForeignAntecedentQuantifier.fingerprints(lease.inventory()).equals(foreignPrints),"all private initialized inventories unchanged");}
        }
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){require(f.db.getRevision()>=afterRevision&&ContextSevenPremiseNativeWriteRunner.origins(ContextSevenPremiseNativeWriteRunner.inventory(f)).equals(settled)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"ordinary durable reopen retains exact settled whole origins and pins");try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){require(lease.bind(WORK,500000).foreign.size()==3,"all private cuts bind after durable reopen");}}
    }
    static void run(boolean negative,String marker){try{for(boolean r:new boolean[]{false,true})for(boolean p:new boolean[]{false,true})for(boolean s:new boolean[]{false,true})for(int m=0;m<3;m++)for(boolean c:new boolean[]{false,true})one(negative,r,p,s,m,c);System.out.println(marker+" checks="+(checks+ContextSevenPremiseNativeWriteRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
